<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'
import { KeyRound, LifeBuoy, Plus, RefreshCw, ShieldOff } from 'lucide-vue-next'
import { api, apiError } from '../api/client';import type { ApiResponse, Paginated, Tenant } from '../types'
import PageHeader from '../components/PageHeader.vue';import SectionTabs from '../components/SectionTabs.vue';import DrawerPanel from '../components/DrawerPanel.vue';import InlineAlert from '../components/InlineAlert.vue';import KeyReveal from '../components/KeyReveal.vue';import StatusBadge from '../components/StatusBadge.vue';import EmptyState from '../components/EmptyState.vue'
interface ApiKey{id:string;name:string;key_prefix:string;permissions:string[];allowed_ips:string[];expires_at?:string;last_used_at?:string;is_active:boolean;created_at:string}
interface Support{id:string;tenant_id:string;platform_user_id:string;reason:string;status:string;expires_at:string;revoked_at?:string;created_at:string}
const tab=ref('keys'),keys=ref<ApiKey[]>([]),sessions=ref<Support[]>([]),tenants=ref<Tenant[]>([]),drawer=ref(false),error=ref(''),success=ref(''),reveal=ref('')
const form=reactive({name:'',permissions:'control.read,control.manage',allowed_ips:'',expires_at:'',tenant_id:'',reason:'Suporte técnico autorizado pelo administrador.',duration_minutes:30})
async function load(){try{const [k,s,t]=await Promise.all([api.get<ApiResponse<ApiKey[]>>('/control/v1/api-keys'),api.get<ApiResponse<Support[]>>('/control/v1/support-sessions'),api.get<Paginated<Tenant>>('/control/v1/tenants',{params:{per_page:100}})]);keys.value=k.data.data;sessions.value=s.data.data;tenants.value=t.data.data}catch(e){error.value=apiError(e)}}
function open(){Object.assign(form,{name:'',permissions:'control.read,control.manage',allowed_ips:'',expires_at:'',tenant_id:tenants.value[0]?.id||'',reason:'Suporte técnico autorizado pelo administrador.',duration_minutes:30});drawer.value=true}
async function create(){try{if(tab.value==='keys'){const r=(await api.post<ApiResponse<{key:string}>>('/control/v1/api-keys',{name:form.name,permissions:form.permissions.split(',').map(v=>v.trim()).filter(Boolean),allowed_ips:form.allowed_ips.split(',').map(v=>v.trim()).filter(Boolean),expires_at:form.expires_at||null})).data.data;reveal.value=r.key}else{const r=(await api.post<ApiResponse<{access_token:string}>>('/control/v1/support-sessions',{tenant_id:form.tenant_id,reason:form.reason,duration_minutes:form.duration_minutes})).data.data;reveal.value=r.access_token}drawer.value=false;await load()}catch(e){error.value=apiError(e)}}
async function revokeKey(item:ApiKey){if(!confirm(`Revogar ${item.name}?`))return;try{await api.delete(`/control/v1/api-keys/${item.id}`);await load()}catch(e){error.value=apiError(e)}}
async function revokeSession(item:Support){try{await api.post(`/control/v1/support-sessions/${item.id}/revoke`);await load()}catch(e){error.value=apiError(e)}}
onMounted(load)
</script>
<template><PageHeader title="Acesso técnico" subtitle="API do Control Plane e sessões temporárias de suporte auditado."><button class="btn-secondary" @click="load"><RefreshCw :size="18"/>Atualizar</button><button class="btn-primary" @click="open"><Plus :size="18"/>{{tab==='keys'?'Nova chave':'Nova sessão'}}</button></PageHeader><InlineAlert :message="error" @dismiss="error=''"/><InlineAlert :message="success" type="success" @dismiss="success=''"/><SectionTabs v-model="tab" :items="[{key:'keys',label:'API Keys',count:keys.length},{key:'support',label:'Sessões de suporte',count:sessions.length}]"/><div v-if="tab==='keys'" class="table-wrap"><table class="table"><thead><tr><th>Chave</th><th>Permissões</th><th>Uso</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in keys" :key="item.id" class="border-t border-slate-100"><td><p class="font-semibold">{{item.name}}</p><p class="font-mono text-xs text-slate-400">{{item.key_prefix}}…</p></td><td><div class="flex max-w-lg flex-wrap gap-1"><span v-for="p in item.permissions" :key="p" class="badge bg-slate-100 text-slate-700">{{p}}</span></div></td><td class="text-xs">{{item.last_used_at?new Date(item.last_used_at).toLocaleString('pt-BR'):'Nunca'}}<p class="text-slate-400">Expira: {{item.expires_at?new Date(item.expires_at).toLocaleDateString('pt-BR'):'não'}}</p></td><td><StatusBadge :status="item.is_active?'ACTIVE':'REVOKED'"/></td><td class="text-right"><button v-if="item.is_active" class="btn-secondary px-3 py-2 text-rose-600" @click="revokeKey(item)"><ShieldOff :size="16"/>Revogar</button></td></tr></tbody></table><EmptyState v-if="!keys.length" title="Nenhuma chave da plataforma"/></div><div v-else class="table-wrap"><table class="table"><thead><tr><th>Tenant</th><th>Motivo</th><th>Validade</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="item in sessions" :key="item.id" class="border-t border-slate-100"><td><RouterLink :to="`/tenants/${item.tenant_id}`" class="font-mono text-xs text-teal-700">{{item.tenant_id}}</RouterLink></td><td class="max-w-lg">{{item.reason}}</td><td>{{new Date(item.expires_at).toLocaleString('pt-BR')}}</td><td><StatusBadge :status="item.status"/></td><td class="text-right"><button v-if="item.status==='ACTIVE'" class="btn-secondary px-3 py-2" @click="revokeSession(item)"><ShieldOff :size="16"/>Revogar</button></td></tr></tbody></table><EmptyState v-if="!sessions.length" title="Nenhuma sessão de suporte"/></div><DrawerPanel :open="drawer" :title="tab==='keys'?'Nova API Key do Control Plane':'Nova sessão de suporte'" width="lg" @close="drawer=false"><form class="space-y-4" @submit.prevent="create"><template v-if="tab==='keys'"><div><label class="label">Nome</label><input v-model="form.name" class="input" required/></div><div><label class="label">Permissões, separadas por vírgula</label><textarea v-model="form.permissions" class="input" rows="3"/></div><div><label class="label">IPs permitidos, separados por vírgula</label><input v-model="form.allowed_ips" class="input" placeholder="vazio = qualquer IP"/></div><div><label class="label">Expiração</label><input v-model="form.expires_at" type="datetime-local" class="input"/></div></template><template v-else><div><label class="label">Tenant</label><select v-model="form.tenant_id" class="select" required><option v-for="item in tenants" :key="item.id" :value="item.id">{{item.name}} · {{item.slug}}</option></select></div><div><label class="label">Motivo obrigatório</label><textarea v-model="form.reason" class="input" rows="4" required/></div><div><label class="label">Duração em minutos</label><input v-model.number="form.duration_minutes" type="number" min="5" max="240" class="input"/></div></template><div class="flex justify-end gap-2 border-t pt-4"><button type="button" class="btn-secondary" @click="drawer=false">Cancelar</button><button class="btn-primary"><component :is="tab==='keys'?KeyRound:LifeBuoy" :size="16"/>Criar</button></div></form></DrawerPanel><KeyReveal :open="!!reveal" :value="reveal" :title="tab==='keys'?'API Key criada':'Token temporário de suporte'" @close="reveal=''"/></template>
